package com.gomgomapps.math.core;
import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class DecimalToFractionSupplyTest {
 @Test public void allDisplayedPrecisionsIgnoreSavedKeys(){int count=0;Checker checker=new Checker();for(int places=1;places<=3;places++){int den=(int)Math.pow(10,places);for(int whole=0;whole<=99;whole++)for(int part=0;part<den;part++){Question q=DecimalToFractionSupply.make(whole,part,places);int num=whole*den+part;q.answers=new String[]{"999999"};q.expression="poison";assertEquals(places,DecimalToFractionSupply.read(q).length()-DecimalToFractionSupply.read(q).indexOf('.')-1);assertTrue(checker.check(q,List.of(),List.of(num+"/"+den)).correct());assertEquals(Checker.Status.WRONG_ANSWER,checker.check(q,List.of(),List.of((num+1)+"/"+den)).status);assertEquals(1,FractionInput.errorPart(q,(num+1)+"/"+den));assertEquals(4,q.studyGuide.frames.size());assertFalse(q.studyGuide.transfer);count++;}}assertEquals(111000,count);}
 @Test public void zeroAndTrailingZerosKeepVisiblePrecision(){for(int p=1;p<=3;p++){Question zero=DecimalToFractionSupply.make(0,0,p);assertEquals("0."+"0".repeat(p),DecimalToFractionSupply.read(zero));assertEquals("decimal-fraction-relations-v1",zero.studyGuide.teachingVersion);assertTrue(new Checker().check(zero,List.of(),List.of("0/17")).correct());assertEquals(0,FractionInput.errorPart(zero,"0/17"));}Question q=DecimalToFractionSupply.make(0,700,3);assertEquals("0.700",DecimalToFractionSupply.read(q));assertTrue(new Checker().check(q,List.of(),List.of("7/10")).correct());assertEquals(2,FractionInput.errorPart(q,"7/11"));assertEquals(2,FractionInput.errorPart(q,"700/1001"));assertEquals(0,FractionInput.errorPart(q,"99/97"));}
 @Test public void yearFiveSuppliesHundredFreshWithEmptyHelp(){var limits=GlobalCurriculum.limits("england-primary-2021-v1",DecimalToFractionSupply.ID,5);assertTrue(DecimalToFractionSupply.selected(DecimalToFractionSupply.ID,limits));Generator gen=new Generator(new Random(180));List<String> recent=new ArrayList<>();Set<Integer> precisions=new HashSet<>();boolean trailing=false;for(int i=0;i<100;i++){Question q=gen.next(DecimalToFractionSupply.ID,recent,false,limits);assertFalse(recent.contains(q.signature()));recent.add(q.signature());String raw=DecimalToFractionSupply.read(q);assertNotNull(raw);precisions.add(raw.length()-raw.indexOf('.')-1);trailing|=raw.endsWith("0");HelpPlan help=HelpPlan.forQuestion(q);assertEquals(4,help.size());assertFalse(help.canTransfer());assertTrue(help.restore(null,q.id).entries.stream().allMatch(String::isEmpty));}assertEquals(Set.of(1,2,3),precisions);assertTrue(trailing);assertFalse(DecimalToFractionSupply.selected(DecimalToFractionSupply.ID,CurriculumLimits.NONE));}
 @Test public void malformedAndFormatRequirementsRemain(){Question q=DecimalToFractionSupply.make(13,33,2);Checker c=new Checker();assertEquals(Checker.Status.INPUT_NEEDED,c.check(q,List.of(),List.of("13.33")).status);assertEquals(Checker.Status.INPUT_NEEDED,c.check(q,List.of(),Arrays.asList((String)null)).status);assertEquals(Checker.Status.INPUT_NEEDED,c.check(q,List.of(),List.of("1/0")).status);q.kind="reduced";assertEquals(Checker.Status.INPUT_NEEDED,c.check(q,List.of(),List.of("2666/200")).status);assertTrue(c.check(q,List.of(),List.of("1333/100")).correct());assertNull(DecimalToFractionSupply.read(new Question(q.skillId,"0.1234567890의 값을 분수로 나타내세요.","","")));try{DecimalToFractionSupply.make(0,100,2);fail();}catch(IllegalArgumentException expected){}}
}
